TEST(BornoCompatParityTest, ReproducesOriginalBornoTSFEngineOutputs) {
    const suborno::layouts::BornoPhoneticLayout borno;
    const suborno::layouts::AvroPhoneticLayout avro;
    const suborno::layouts::KhiproLayout khipro;

    // Pure-parser comparison: the reference harness ran with phonetic

    // correction disabled (stub autocorrect), so mirror that here.

    borno_compat::set_phonetic_correction(false);

    for (const ParityRow& row : parity_rows) {
        EXPECT_EQ(borno.transliterate(row.input), row.borno) << "borno: " << row.input;
        EXPECT_EQ(avro.transliterate(row.input), row.avro) << "avro: " << row.input;
        EXPECT_EQ(khipro.transliterate(row.input), row.khipro) << "khipro: " << row.input;
    }

    // Restore the product default (enabled) exactly like BornoTSF's

    // registry default.

    borno_compat::set_phonetic_correction(true);
}

TEST(BornoCompatParityTest, AutocorrectPassThroughMatchesBornoTSF) {
    // With correction on, emoticon identity entries pass through untouched

    // and respelling entries re-parse (BornoTSF getAutoCorrect contract).

    const suborno::layouts::BornoPhoneticLayout borno;
    ASSERT_TRUE(borno_compat::get_phonetic_correction());
    EXPECT_EQ(borno.transliterate(":)"), ":)");
    EXPECT_EQ(borno.transliterate("xD"), "xD");
    EXPECT_EQ(borno.transliterate("dhaka"), "\u09A2\u09BE\u0995\u09BE");
}
